-- ============================================================================
-- Generated by reverse-engineering the entire Fameu codebase:
--   • backend/src/services/*.service.js
--   • backend/src/api/**/*.js
--   • backend/src/jobs/*.js
--   • backend/src/sockets/socketManager.js
