--
-- HOW TO USE:
--   1. Install Supabase on your new VPS (follow https://supabase.com/docs/guides/self-hosting)
--   2. Connect to the PostgreSQL instance:
--        psql -h localhost -p 5432 -U supabase_admin -d postgres
--   3. Run this entire file:
--        \i /path/to/complete_schema.sql
--
-- IMPORTANT:
--   • This script assumes Supabase Auth is already set up (auth.users table exists).
--   • The backend uses the service_role key, so RLS is bypassed in production.
--   • RLS policies are included but disabled by default (match existing behavior).
--   • Run this BEFORE starting the backend server.
-- ============================================================================


-- ============================================================================
-- 0. EXTENSIONS (Supabase usually pre-installs these, but just in case)
-- ============================================================================
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";


-- ============================================================================
-- 1. CORE USER TABLE
-- ============================================================================
-- Referenced by: auth.users (FK), all other tables via user_id
-- Source: schema.sql:1-17, auth.service.js, connection.service.js, admin_panel

CREATE TABLE IF NOT EXISTS public.users (
  id                  UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  mobile              TEXT UNIQUE,
  email               TEXT UNIQUE,
  username            TEXT UNIQUE,
  display_name        TEXT,
  avatar_url          TEXT,
  role                TEXT NOT NULL DEFAULT 'artist'
                      CHECK (role IN ('artist', 'hiring', 'admin')),
  followers_count     INT DEFAULT 0,
  following_count     INT DEFAULT 0,
  is_active           BOOLEAN DEFAULT TRUE,
  is_blacklisted      BOOLEAN DEFAULT FALSE,
  disclaimer_accepted BOOLEAN DEFAULT FALSE,
  fcm_token           TEXT,
  created_at          TIMESTAMPTZ DEFAULT NOW(),
  updated_at          TIMESTAMPTZ DEFAULT NOW()
);

COMMENT ON TABLE public.users IS 'Public user profile — mirrors auth.users via trigger. Role determines app access (artist/hiring/admin).';
COMMENT ON COLUMN public.users.fcm_token IS 'Firebase Cloud Messaging token for push notifications. Updated by POST /notification/fcm-token.';
COMMENT ON COLUMN public.users.disclaimer_accepted IS 'Whether user accepted the platform disclaimer/terms. Added via update_schema.sql.';


-- ============================================================================
-- 2. AUTH TRIGGER: auto-create public.users on Supabase Auth signup
-- ============================================================================
-- Source: schema.sql:20-38, auth.service.js (verifyOtp creates via admin API)

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.users (id, email, mobile, role, display_name, avatar_url)
  VALUES (
    NEW.id,
    NEW.email,
    NEW.phone,
    COALESCE(NEW.raw_user_meta_data->>'role', 'artist'),
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'avatar_url'
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Drop if exists to avoid conflicts on re-run
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();


