-- ============================================================================
-- Source: schema.sql:40-47, auth.service.js (sendOtp, verifyOtp)

CREATE TABLE IF NOT EXISTS public.otp_store (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  identifier  TEXT NOT NULL,                    -- email or phone number
  otp         TEXT NOT NULL,                    -- 4-digit OTP string
  expires_at  TIMESTAMPTZ NOT NULL,             -- 10 min from creation
  created_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS otp_store_identifier_idx ON public.otp_store(identifier);

COMMENT ON TABLE public.otp_store IS 'Temporary OTP storage. Upserted on send, deleted after verification. Keyed by identifier (email/phone).';


