-- 4. ARTIST PROFILES (Base profile for artist-role users)
-- ============================================================================
-- Source: schema.sql:49-89, artist.service.js, connection.service.js
-- IMPORTANT: visit_count column is NOT in original schema.sql but IS used in
-- connection.service.js:167-168 and artist.service.js:174

CREATE TABLE IF NOT EXISTS public.artist_profiles (
  id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id               UUID UNIQUE REFERENCES public.users(id) ON DELETE CASCADE,
  full_name             TEXT,
  categories            TEXT[],               -- e.g. ['Actor', 'Singer', 'Model']
  age                   INT,
  gender                TEXT,                 -- 'Male', 'Female', 'Other'
  height                TEXT,                 -- stored as text like "5'10\""
  weight                TEXT,                 -- stored as text like "75kg"
  city                  TEXT,
  bio                   TEXT,
  experience            TEXT,                 -- experience level text
  languages             TEXT[],
  skills                TEXT[],
  avatar_url            TEXT,
  photo_urls            TEXT[],               -- gallery, max 10 photos
  video_url             TEXT,                 -- comma-separated URLs (legacy) or single URL
  resume_url            TEXT,
  audio_url             TEXT,
  social_links          JSONB,                -- e.g. {"instagram":"...", "youtube":"..."}
  is_cintaa_member      BOOLEAN DEFAULT FALSE,
  cintaa_reg_number     TEXT,
  availability_type     TEXT,                 -- 'full_time', 'part_time', 'freelance'
  available_dates       JSONB,                -- flexible date range JSON
  work_preference       TEXT[],               -- e.g. ['Bollywood', 'OTT', 'Ad Films']
  preferred_cities      TEXT[],
  look_alike            TEXT[],               -- celebrity look-alike tags
  hashtags              TEXT[],               -- profile hashtags
  intro_video_url       TEXT,                 -- separate from portfolio video
  left_profile_url      TEXT,                 -- left-side photo for comp card
  right_profile_url     TEXT,                 -- right-side photo for comp card
  recent_assignments    JSONB,                -- array of {title, role, year}
  alternate_phone       TEXT,
  alternate_email       TEXT,
  is_verified           BOOLEAN DEFAULT FALSE,
  verification_status   TEXT DEFAULT 'unverified',  -- 'unverified', 'pending', 'verified', 'rejected'
  profile_complete_pct  INT DEFAULT 0,        -- 0-100 percentage
  travel_available      BOOLEAN DEFAULT FALSE,
  visit_count           INT DEFAULT 0,        -- profile view counter (connection.service.js)
  created_at            TIMESTAMPTZ DEFAULT NOW(),
  updated_at            TIMESTAMPTZ DEFAULT NOW()
);

COMMENT ON TABLE public.artist_profiles IS 'Base artist profile. One-to-one with users (user_id UNIQUE). Categories drive which dynamic detail forms are shown.';
COMMENT ON COLUMN public.artist_profiles.visit_count IS 'Incremented by connection.service.js:recordProfileVisit(). Not in original schema.sql but actively used.';


