  updated_at      TIMESTAMPTZ DEFAULT NOW(),
  CONSTRAINT fk_participant1 FOREIGN KEY (participant1_id) REFERENCES public.users(id) ON DELETE CASCADE,
  CONSTRAINT fk_participant2 FOREIGN KEY (participant2_id) REFERENCES public.users(id) ON DELETE CASCADE,
  UNIQUE(participant1_id, participant2_id)
);

COMMENT ON TABLE public.conversations IS 'Chat conversations. Participants are always ordered (p1 < p2) to prevent duplicates. last_message updated on each new message.';


-- ============================================================================
-- 25. CHAT: MESSAGES
-- ============================================================================
-- Source: schema.sql:320-328, chat.service.js, socketManager.js

CREATE TABLE IF NOT EXISTS public.messages (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id UUID REFERENCES public.conversations(id) ON DELETE CASCADE,
  sender_id       UUID REFERENCES public.users(id) ON DELETE CASCADE,
  content         TEXT NOT NULL,
  is_read         BOOLEAN DEFAULT FALSE,
  created_at      TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_messages_conv_created ON public.messages(conversation_id, created_at DESC);


-- ============================================================================
-- 26. CHECK-INS (Walk-in audition geolocation check-in)
-- ============================================================================
-- Source: schema.sql:330-337, audition.service.js:338-356

CREATE TABLE IF NOT EXISTS public.checkins (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  artist_id       UUID REFERENCES public.artist_profiles(id) ON DELETE CASCADE,
  audition_id     UUID REFERENCES public.auditions(id) ON DELETE CASCADE,
  lat             DOUBLE PRECISION,
  lng             DOUBLE PRECISION,
  created_at      TIMESTAMPTZ DEFAULT NOW()
);


-- ============================================================================
-- 27. PROFILE VISITS (Who visited whose profile)
-- ============================================================================
-- Source: schema.sql:371-378, connection.service.js:220-232, 307-347
-- NOTE: The code uses `visit_date` column (not `visited_at` from original schema).
-- We include both for safety.

CREATE TABLE IF NOT EXISTS public.profile_visits (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
  viewer_id       UUID REFERENCES public.users(id) ON DELETE CASCADE,
  visited_at      TIMESTAMPTZ DEFAULT NOW(),   -- original schema column
  visit_date      TIMESTAMPTZ DEFAULT NOW(),   -- used by connection.service.js
  UNIQUE(profile_user_id, viewer_id)
);

CREATE INDEX IF NOT EXISTS idx_profile_visits_user_date ON public.profile_visits(profile_user_id, visited_at DESC);

COMMENT ON TABLE public.profile_visits IS 'Records profile visits. Upserted on each visit (only latest visit kept per viewer). visit_date is the column used by backend code.';


