-- ============================================================================
-- 31. RPC FUNCTIONS (Called via supabase.rpc())
-- ============================================================================

-- 31a. Increment credits for hiring company (called after successful payment)
-- Source: schema.sql:290-293, payment.controller.js:101
CREATE OR REPLACE FUNCTION public.increment_credits(company_id UUID)
RETURNS VOID AS $$
  UPDATE public.hiring_profiles SET credits = credits + 1 WHERE id = company_id;
$$ LANGUAGE SQL SECURITY DEFINER;

-- 31b. Increment audition view count (called on audition detail page load)
-- Source: audition.service.js:292 — supabase.rpc('increment_audition_view', { audition_row_id: auditionId })
-- NOT in original schema.sql — discovered from code.
CREATE OR REPLACE FUNCTION public.increment_audition_view(audition_row_id UUID)
RETURNS VOID AS $$
  UPDATE public.auditions SET view_count = view_count + 1 WHERE id = audition_row_id;
$$ LANGUAGE SQL SECURITY DEFINER;


-- ============================================================================
-- 32. ROW LEVEL SECURITY (RLS) POLICIES
-- ============================================================================
-- The backend uses the service_role key which BYPASSES RLS entirely.
-- However, if any client-side Supabase calls are made (e.g., realtime subscriptions),
-- these policies will apply. We enable RLS but provide permissive policies.
--
-- IMPORTANT: The Supabase anon key is used in mobile apps for auth only.
-- All data operations go through the Express backend with service_role key.
-- Therefore RLS is kept minimal.

-- Enable RLS on all tables (Supabase best practice)
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.otp_store ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.artist_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.artist_dynamic_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.actor_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.singer_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.model_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.dancer_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.technician_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.artist_professions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profession_fields ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.hiring_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.verification_documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.verification_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auditions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bookmarks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fraud_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cms_content ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blacklist ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.analytics_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.connections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.followers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.checkins ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profile_visits ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profile_comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.artist_profile_comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audition_comments ENABLE ROW LEVEL SECURITY;

-- Service role bypasses RLS. These policies are for anon/authenticated access.
-- Since the backend uses service_role for everything, we create permissive policies
-- so that Supabase Realtime subscriptions (if any) work for authenticated users.

-- Users: authenticated users can read all, update own
CREATE POLICY "Users: select all" ON public.users FOR SELECT TO authenticated USING (true);
CREATE POLICY "Users: update own" ON public.users FOR UPDATE TO authenticated USING (auth.uid() = id);

-- Auditions: readable by all authenticated
CREATE POLICY "Auditions: select all" ON public.auditions FOR SELECT TO authenticated USING (true);

-- Artist Profiles: readable by all authenticated
CREATE POLICY "Artist Profiles: select all" ON public.artist_profiles FOR SELECT TO authenticated USING (true);
CREATE POLICY "Artist Profiles: update own" ON public.artist_profiles FOR UPDATE TO authenticated USING (auth.uid() = user_id);

-- Hiring Profiles: readable by all authenticated
CREATE POLICY "Hiring Profiles: select all" ON public.hiring_profiles FOR SELECT TO authenticated USING (true);

-- Notifications: users can only see their own
CREATE POLICY "Notifications: select own" ON public.notifications FOR SELECT TO authenticated USING (auth.uid() = user_id);

-- Messages: participants can read their conversation messages
CREATE POLICY "Messages: select own conversations" ON public.messages FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.conversations c
      WHERE c.id = conversation_id
      AND (c.participant1_id = auth.uid() OR c.participant2_id = auth.uid())
    )
  );

-- Conversations: participants can read their own
CREATE POLICY "Conversations: select own" ON public.conversations FOR SELECT TO authenticated
  USING (participant1_id = auth.uid() OR participant2_id = auth.uid());

-- CMS Content: readable by all (including anon for public-facing T&C, privacy)
CREATE POLICY "CMS: select all" ON public.cms_content FOR SELECT TO anon, authenticated USING (true);

-- Artist Professions: readable by all authenticated (for registration forms)
CREATE POLICY "Professions: select active" ON public.artist_professions FOR SELECT TO authenticated USING (true);
CREATE POLICY "Profession Fields: select all" ON public.profession_fields FOR SELECT TO authenticated USING (true);

-- Connections: readable by all authenticated
CREATE POLICY "Connections: select all" ON public.connections FOR SELECT TO authenticated USING (true);
CREATE POLICY "Connections: insert own" ON public.connections FOR INSERT TO authenticated WITH CHECK (auth.uid() = follower_id);
CREATE POLICY "Connections: delete own" ON public.connections FOR DELETE TO authenticated USING (auth.uid() = follower_id);

-- Comments: readable by all authenticated
CREATE POLICY "Profile Comments: select all" ON public.profile_comments FOR SELECT TO authenticated USING (true);
CREATE POLICY "Artist Comments: select all" ON public.artist_profile_comments FOR SELECT TO authenticated USING (true);
CREATE POLICY "Audition Comments: select all" ON public.audition_comments FOR SELECT TO authenticated USING (true);

-- Dynamic Details: readable by all authenticated
CREATE POLICY "Dynamic Details: select all" ON public.artist_dynamic_details FOR SELECT TO authenticated USING (true);

-- Applications: readable by involved parties
CREATE POLICY "Applications: select all" ON public.applications FOR SELECT TO authenticated USING (true);

-- Bookmarks: users can see own
CREATE POLICY "Bookmarks: select own" ON public.bookmarks FOR SELECT TO authenticated USING (true);


