-- ============================================================================
-- 34. STORAGE BUCKETS (Supabase Storage — if migrating from local disk)
-- ============================================================================
-- The current backend stores files on LOCAL DISK (uploads/ directory) and
-- serves them via Express static file serving. If you want to use Supabase
-- Storage instead, create these buckets:
--
-- INSERT INTO storage.buckets (id, name, public) VALUES
--   ('artist', 'artist', true),           -- artist photos, videos, resumes, audio
--   ('company', 'company', true),         -- company logos
--   ('verification', 'verification', false), -- KYC documents (private)
--   ('thumbnails', 'thumbnails', true);   -- audition thumbnails
--
-- NOTE: The backend currently uses Express multer + local disk storage.
-- File URLs are in the format: https://api.fameu.in/uploads/artist/<filename>
-- No migration to Supabase Storage is needed unless you choose to switch.


-- ============================================================================
-- 35. GRANTS (Ensure proper role access)
-- ============================================================================
-- Supabase uses the following roles:
--   anon: unauthenticated API calls
--   authenticated: authenticated API calls
--   service_role: backend server (full access, bypasses RLS)

-- Grant usage on public schema
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;

-- Grant access to all tables
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO authenticated;

-- Grant access to sequences (for gen_random_uuid, etc.)
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;

-- Grant execute on functions
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated, service_role;

-- Ensure future tables get the same grants
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO anon;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE ON SEQUENCES TO anon, authenticated, service_role;


